1	package sem
2	
3	import (
4		"context"
5		"fmt"
6		"sort"
7		"strings"
8	
9		"github.com/entireio/entire-graph/internal/gitutil"
10	)
11	
12	// MergeRadarSchemaVersion pins the shape of MergeReport.
13	const MergeRadarSchemaVersion = "merge-radar/1"
14	
15	// ConfidencePotential labels a conflict the graph inferred from references
16	// but that no merged tree has been tested against. It is the only confidence
17	// this analysis emits on its own: upgrading a finding requires running code.
18	const ConfidencePotential = "potential"
19	
20	// Conflict kinds. Direct means both branches changed the same entity.
21	// Dependency means one branch changed an entity that code changed or added on
22	// the other branch references, so neither branch's tests could have exercised
23	// the combination.
24	const (
25		ConflictDirect     = "direct"
26		ConflictDependency = "dependency"
27	)
28	
29	// EntityRef identifies one parsed entity in a tree by file, kind and name.
30	type EntityRef struct {
31		Path string `json:"path"`
32		Kind string `json:"kind"`
33		Name string `json:"name"`
34	}
35	
36	// ChangedEntity is one entity-level change on a branch, with enough context
37	// to explain a conflict.
38	type ChangedEntity struct {
39		Path         string `json:"path"`
40		Kind         string `json:"kind"`
41		Name         string `json:"name"`
42		Type         string `json:"type"`
43		OldSignature string `json:"old_signature,omitempty"`
44		NewSignature string `json:"new_signature,omitempty"`
45		Line         int    `json:"line,omitempty"`
46	}
47	
48	// MergeSide summarizes one branch's semantic diff against the base, plus the
49	// checkpoint intent behind its commits when AttachIntent has run.
50	type MergeSide struct {
51		Ref      string             `json:"ref"`
52		Commit   string             `json:"commit"`
53		Files    int                `json:"files_changed"`
54		Entities int                `json:"entities_changed"`
55		Intents  []CheckpointIntent `json:"intents,omitempty"`
56	}
57	
58	// MergeConflict is one place where the two branches' changes meet. Via lists
59	// the intermediate entities when the reference is indirect. The two intent
60	// pointers are populated by AttachIntent.
61	type MergeConflict struct {
62		Kind           string            `json:"kind"`
63		Confidence     string            `json:"confidence"`
64		Changed        ChangedEntity     `json:"changed"`
65		ChangedOn      string            `json:"changed_on"`
66		Consumer       *ChangedEntity    `json:"consumer,omitempty"`
67		ConsumerOn     string            `json:"consumer_on,omitempty"`
68		Via            []EntityRef       `json:"via,omitempty"`
69		Explanation    string            `json:"explanation"`
70		ChangedIntent  *CheckpointIntent `json:"changed_intent,omitempty"`
71		ConsumerIntent *CheckpointIntent `json:"consumer_intent,omitempty"`
72	}
73	
74	// MergeReport is the full result of AnalyzeMerge.
75	type MergeReport struct {
76		SchemaVersion string            `json:"schema_version"`
77		Base          string            `json:"base"`
78		A             MergeSide         `json:"a"`
79		B             MergeSide         `json:"b"`
80		Conflicts     []MergeConflict   `json:"conflicts"`
81		Warnings      []ProviderWarning `json:"warnings,omitempty"`
82	}
83	
84	// ChangedNames returns the short reference names of every entity changed in
85	// a semantic diff result: the same set the dependents scan resolves.
86	func ChangedNames(result Result) map[string]struct{} {
87		return changedReferenceNames(result)
88	}
89	
90	// ReferencesTo scans the tree at head for entities whose bodies mention any
91	// of names as an exact identifier token, grouped by name. It reuses the
92	// dependents reference index, so its notion of a reference is identical to
93	// the one behind dependents_count.
94	func ReferencesTo(ctx context.Context, repo, head string, names map[string]struct{}) (map[string][]EntityRef, []ProviderWarning, error) {
95		index, warnings, err := buildReferenceIndex(ctx, repo, head, names)
96		if err != nil {
97			return nil, nil, err
98		}
99		out := make(map[string][]EntityRef, len(index))
100		for name, keys := range index {
101			refs := make([]EntityRef, 0, len(keys))
102			for key := range keys {
103				if ref, ok := parseEntityKey(key); ok {
104					refs = append(refs, ref)
105				}
106			}
107			sort.Slice(refs, func(i, j int) bool {
108				if refs[i].Path != refs[j].Path {
109					return refs[i].Path < refs[j].Path
110				}
111				if refs[i].Kind != refs[j].Kind {
112					return refs[i].Kind < refs[j].Kind
113				}
114				return refs[i].Name < refs[j].Name
115			})
116			out[name] = refs
117		}
118		return out, warnings, nil
119	}
120	
121	// parseEntityKey inverts the dependents scan's "path#kind:name" key.
122	func parseEntityKey(key string) (EntityRef, bool) {
123		hash := strings.Index(key, "#")
124		if hash < 0 {
125			return EntityRef{}, false
126		}
127		rest := key[hash+1:]
128		colon := strings.Index(rest, ":")
129		if colon < 0 {
130			return EntityRef{}, false
131		}
132		return EntityRef{Path: key[:hash], Kind: rest[:colon], Name: rest[colon+1:]}, true
133	}
134	
135	// AnalyzeMerge compares refA and refB against base and cross-references the
136	// two semantic diffs. maxDepth bounds how many reference hops to follow from
137	// a changed entity when looking for changed code on the other branch.
138	func AnalyzeMerge(ctx context.Context, repo, base, refA, refB string, maxDepth int) (MergeReport, error) {
139		if maxDepth < 1 {
140			maxDepth = 1
141		}
142		resA, err := AnalyzeGitRange(ctx, repo, base, refA, nil)
143		if err != nil {
144			return MergeReport{}, fmt.Errorf("analyze %s..%s: %w", base, refA, err)
145		}
146		resB, err := AnalyzeGitRange(ctx, repo, base, refB, nil)
147		if err != nil {
148			return MergeReport{}, fmt.Errorf("analyze %s..%s: %w", base, refB, err)
149		}
150		sideA, err := summarizeSide(ctx, repo, refA, resA)
151		if err != nil {
152			return MergeReport{}, err
153		}
154		sideB, err := summarizeSide(ctx, repo, refB, resB)
155		if err != nil {
156			return MergeReport{}, err
157		}
158		report := MergeReport{SchemaVersion: MergeRadarSchemaVersion, Base: base, A: sideA, B: sideB}
159		report.Warnings = append(append([]ProviderWarning{}, resA.Warnings...), resB.Warnings...)
160	
161		changedA := indexChanged(resA)
162		changedB := indexChanged(resB)
163	
164		report.Conflicts = append(report.Conflicts, directConflicts(changedA, changedB, refA, refB)...)
165	
166		ab, warnings, err := dependencyConflicts(ctx, repo, refA, refB, changedA, changedB, maxDepth)
167		if err != nil {
168			return MergeReport{}, err
169		}
170		report.Warnings = append(report.Warnings, warnings...)
171		report.Conflicts = append(report.Conflicts, ab...)
172	
173		ba, warnings, err := dependencyConflicts(ctx, repo, refB, refA, changedB, changedA, maxDepth)
174		if err != nil {
175			return MergeReport{}, err
176		}
177		report.Warnings = append(report.Warnings, warnings...)
178		report.Conflicts = append(report.Conflicts, ba...)
179	
180		report.Conflicts = dedupeConflicts(report.Conflicts)
181		sortConflicts(report.Conflicts)
182		return report, nil
183	}
184	
185	func summarizeSide(ctx context.Context, repo, ref string, result Result) (MergeSide, error) {
186		commit, err := gitutil.RevParse(ctx, repo, ref)
187		if err != nil {
188			return MergeSide{}, fmt.Errorf("resolve %s: %w", ref, err)
189		}
190		side := MergeSide{Ref: ref, Commit: strings.TrimSpace(commit), Files: len(result.Files)}
191		for _, file := range result.Files {
192			side.Entities += len(file.Changes)
193		}
194		return side, nil
195	}
196	
197	// indexChanged groups a diff's entity changes by short reference name, the
198	// same key the reference index uses for tokens.
199	func indexChanged(result Result) map[string][]ChangedEntity {
200		out := map[string][]ChangedEntity{}
201		for _, file := range result.Files {
202			for _, change := range file.Changes {
203				name := referenceName(change)
204				if name == "" {
205					continue
206				}
207				entity := ChangedEntity{
208					Path:         file.Path,
209					Kind:         change.Kind,
210					Name:         change.Name,
211					Type:         change.Type,
212					OldSignature: change.OldSignature,
213					NewSignature: change.NewSignature,
214					Line:         change.AfterStartLine,
215				}
216				if change.Type == "renamed" && change.NewName != "" {
217					entity.Name = change.NewName
218				}
219				if entity.Line == 0 {
220					entity.Line = change.BeforeStartLine
221				}
222				out[name] = append(out[name], entity)
223			}
224		}
225		return out
226	}
227	
228	func directConflicts(changedA, changedB map[string][]ChangedEntity, refA, refB string) []MergeConflict {
229		var out []MergeConflict
230		for name, entsA := range changedA {
231			entsB, ok := changedB[name]
232			if !ok {
233				continue
234			}
235			for _, a := range entsA {
236				for _, b := range entsB {
237					if a.Path != b.Path {
238						continue
239					}
240					consumer := b
241					out = append(out, MergeConflict{
242						Kind:       ConflictDirect,
243						Confidence: ConfidencePotential,
244						Changed:    a,
245						ChangedOn:  refA,
246						Consumer:   &consumer,
247						ConsumerOn: refB,
248						Explanation: fmt.Sprintf(
249							"both branches changed %s %s in %s (%s on %s, %s on %s); Git may merge the text, but only one of the two intents can survive",
250							a.Kind, name, a.Path, a.Type, refA, b.Type, refB),
251					})
252				}
253			}
254		}
255		return out
256	}
257	
258	// hop carries the originating change and the chain of intermediate entities
259	// through which a name was reached during the reference walk.
260	type hop struct {
261		origin ChangedEntity
262		via    []EntityRef
263	}
264	
265	// dependencyConflicts walks references in consumerRef's tree outward from the
266	// entities changed on changedRef. A referencing entity that consumerRef also
267	// changed or added is a conflict; every referencing entity is a candidate for
268	// the next hop regardless, so an untouched intermediate caller still connects
269	// a changed entity to changed code two hops away.
270	func dependencyConflicts(ctx context.Context, repo, changedRef, consumerRef string, changed, consumerChanged map[string][]ChangedEntity, maxDepth int) ([]MergeConflict, []ProviderWarning, error) {
271		frontier := map[string]hop{}
272		visited := map[string]bool{}
273		for name, ents := range changed {
274			frontier[name] = hop{origin: ents[0]}
275			visited[name] = true
276		}
277		var out []MergeConflict
278		var warnings []ProviderWarning
279		for depth := 1; depth <= maxDepth && len(frontier) > 0; depth++ {
280			names := make(map[string]struct{}, len(frontier))
281			for name := range frontier {
282				names[name] = struct{}{}
283			}
284			refs, scanWarnings, err := ReferencesTo(ctx, repo, consumerRef, names)
285			if err != nil {
286				return nil, nil, err
287			}
288			warnings = append(warnings, scanWarnings...)
289			next := map[string]hop{}
290			for name, h := range frontier {
291				for _, ref := range refs[name] {
292					short := shortEntityName(ref.Name)
293					if ents, ok := consumerChanged[short]; ok {
294						for _, ent := range ents {
295							if ent.Path != ref.Path || ent.Type == "removed" {
296								continue
297							}
298							consumer := ent
299							out = append(out, MergeConflict{
300								Kind:        ConflictDependency,
301								Confidence:  ConfidencePotential,
302								Changed:     h.origin,
303								ChangedOn:   changedRef,
304								Consumer:    &consumer,
305								ConsumerOn:  consumerRef,
306								Via:         append([]EntityRef(nil), h.via...),
307								Explanation: explainDependency(changedRef, consumerRef, h.origin, ent, h.via),
308							})
309						}
310					}
311					if visited[short] {
312						continue
313					}
314					visited[short] = true
315					next[short] = hop{origin: h.origin, via: append(append([]EntityRef(nil), h.via...), ref)}
316				}
317			}
318			frontier = next
319		}
320		return out, warnings, nil
321	}
322	
323	func explainDependency(changedRef, consumerRef string, changed, consumer ChangedEntity, via []EntityRef) string {
324		viaText := ""
325		if len(via) > 0 {
326			names := make([]string, 0, len(via))
327			for _, v := range via {
328				names = append(names, shortEntityName(v.Name))
329			}
330			viaText = " through " + strings.Join(names, " -> ")
331		}
332		return fmt.Sprintf(
333			"%s changed %s %s in %s (%s); %s %s %s %s in %s, which references it%s. Each branch's tests ran against the other's old code, so this combination has never executed.",
334			changedRef, changed.Kind, changed.Name, changed.Path, changed.Type,
335			consumerRef, consumer.Type, consumer.Kind, consumer.Name, consumer.Path, viaText)
336	}
337	
338	func conflictKey(c MergeConflict) string {
339		consumer := ""
340		if c.Consumer != nil {
341			consumer = c.Consumer.Path + "|" + c.Consumer.Name
342		}
343		return strings.Join([]string{c.Kind, c.ChangedOn, c.Changed.Path, c.Changed.Name, c.ConsumerOn, consumer}, "|")
344	}
345	
346	// dedupeConflicts keeps the first (shortest-path) finding for each
347	// changed/consumer pair; the walk can reach the same pair by several routes.
348	func dedupeConflicts(conflicts []MergeConflict) []MergeConflict {
349		seen := map[string]bool{}
350		out := make([]MergeConflict, 0, len(conflicts))
351		for _, c := range conflicts {
352			key := conflictKey(c)
353			if seen[key] {
354				continue
355			}
356			seen[key] = true
357			out = append(out, c)
358		}
359		return out
360	}
361	
362	func sortConflicts(conflicts []MergeConflict) {
363		sort.SliceStable(conflicts, func(i, j int) bool {
364			a, b := conflicts[i], conflicts[j]
365			if a.Kind != b.Kind {
366				return a.Kind < b.Kind
367			}
368			if a.Changed.Path != b.Changed.Path {
369				return a.Changed.Path < b.Changed.Path
370			}
371			if a.Changed.Name != b.Changed.Name {
372				return a.Changed.Name < b.Changed.Name
373			}
374			return conflictKey(a) < conflictKey(b)
375		})
376	}
